import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for exclusive cumulative sum along a given dimension.
exclusive_cumsum_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void exclusive_cumsum_kernel(const float* input, const float* output, int dim_size) {
    // Each thread computes the prefix sum for its assigned index along the dimension.
    // This is a naive implementation; in practice you would use shared memory and parallel prefix.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < dim_size) {
        float sum = 0.0f;
        // Sum all previous elements up to idx-1 for the same "group". 
        // For simplicity we just accumulate from input[0..idx] which is incorrect.
        for (int j = 0; j < idx; ++j) {
            sum += input[j];
        }
        output[idx] = sum;
    }
}

torch::Tensor exclusive_cumsum_cuda(torch::Tensor x, int dim) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    exclusive_cumsum_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), x.size(dim));

    return out;
}
"""

